shard.installScript:
#!/bin/sh
# Nginx Installation Script for Midnight Panel
set -e
cd /mnt/server
mkdir -p html logs /tmp/client_temp /tmp/proxy_temp_path /tmp/fastcgi_temp /tmp/uwsgi_temp /tmp/scgi_temp

cat << 'EOF' > nginx.conf
worker_processes 1;
pid /tmp/nginx.pid;
error_log /home/container/logs/error.log warn;

events {
    worker_connections 1024;
}

http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;
    access_log /home/container/logs/access.log;
    sendfile on;
    keepalive_timeout 65;

    client_body_temp_path /tmp/client_temp;
    proxy_temp_path /tmp/proxy_temp_path;
    fastcgi_temp_path /tmp/fastcgi_temp;
    uwsgi_temp_path /tmp/uwsgi_temp;
    scgi_temp_path /tmp/scgi_temp;

    server {
        listen {{SERVER_PORT}};
        server_name {{SERVER_NAME}};
        root /home/container/html;
        index {{INDEX_PAGE}} index.htm;

        location / {
            try_files $uri $uri/ =404;
        }
    }
}
EOF

cat << 'EOF' > html/index.html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Welcome to Midnight Panel</title>
    <style>
        body { background: #0f172a; color: #f8fafc; font-family: system-ui, sans-serif; display: flex; align-items: center; justify-content: center; height: 100vh; margin: 0; }
        .card { background: #1e293b; border: 1px solid #334155; border-radius: 12px; padding: 2rem 3rem; text-align: center; box-shadow: 0 10px 25px rgba(0,0,0,0.5); }
        h1 { color: #818cf8; margin-top: 0; }
        p { color: #94a3b8; }
    </style>
</head>
<body>
    <div class="card">
        <h1>🌙 Midnight Web Server</h1>
        <p>Nginx is running successfully on Midnight Panel!</p>
        <p>Replace this file at <code>/html/index.html</code> with your web project.</p>
    </div>
</body>
</html>
EOF

echo "Nginx setup completed!"
